19	type Task = {
20	  id: number;
21	  projectId: number;
22	  title: string;
23	  done: boolean;
24	};
25	
26	export function ProjectDetail({ projectId }: { projectId: number }) {
27	  const [invoices, setInvoices] = useState<Invoice[]>([]);
28	  const [tasks, setTasks] = useState<Task[]>([]);
29	  // Which tasks to show: all of them, just the open ones, or just the finished ones.
30	  const [taskFilter, setTaskFilter] = useState('');
31	  const [amount, setAmount] = useState('');
32	  const [amountError, setAmountError] = useState(false);
33	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
34	
35	  async function load() {
36	    const res = await fetch(`/api/projects/${projectId}/invoices`);
37	    if (res.ok) {
38	      setInvoices(await res.json());
39	    }
40	  }
41	
42	  async function loadTasks() {
43	    const query = taskFilter ? `?filter=${encodeURIComponent(taskFilter)}` : '';
44	    const res = await fetch(`/api/projects/${projectId}/tasks${query}`);
45	    if (res.ok) {
46	      setTasks(await res.json());
47	    }
48	  }
49	
50	  useEffect(() => {
51	    void load();
52	  }, [projectId]);
53	
54	  useEffect(() => {
55	    void loadTasks();
56	  }, [projectId, taskFilter]);
57	
58	  // Tick a task off (or back on): toggles OPEN <-> DONE and reloads the list.
59	  async function onToggleTask(taskId: number) {
60	    const res = await fetch(`/api/tasks/${taskId}/toggle`, { method: 'POST' });
61	    if (res.ok) {
62	      await loadTasks();
63	    }
64	  }
65	
66	  async function onSubmit(event: FormEvent) {
67	    event.preventDefault();
68	    // An invoice must be for a real amount: a positive number, never zero or negative.
69	    const value = Number(amount);
70	    if (!(value > 0)) {
71	      setAmountError(true);
72	      return;
